"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Un serveur Model Context Protocol donne à un agent de codage des outils supplémentaires : fichiers, web, navigateur, GitHub et autres. Cela ne concerne que les agents qui se connectent via leur propre outil en ligne de commande dans Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — un agent utilisé uniquement avec une clé d’API ne peut pas en utiliser ici.",
