"App: ADB Application Manager Pro ? (build ?)": "Application : ADB Application Manager Pro ? (build ?)",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner peut vider les caches qu’aucun accès aux fichiers n’atteint (le bouton « Vider le cache » de l’écran Stockage d’une application) en appuyant à votre place dans les paramètres du système. Pour cela, il a besoin du service d’accessibilité de cette application. Le service n’agit que pendant que AppCleaner vide des caches : il ouvre l’écran Infos de l’application d’une application après l’autre, appuie sur Vider le cache, et s’arrête quand l’écran s’éteint ou se verrouille. Un voile sur l’écran montre ce qu’il fait, avec un moyen d’annuler. Rien n’est lu ni envoyé nulle part. Sous Android 13 et plus récent, une application installée depuis un fichier peut d’abord avoir besoin de « Autoriser les paramètres restreints » (Infos de l’application de cette application, menu à trois points).",
