"Browser Use": "Browser Use",
"Browser Use is an open-source library that lets an AI model drive a web browser to do a task. It runs on a computer with Python and needs a key for the AI model it uses (its own cloud gives new accounts some free credit, then it is paid). It has no Android version and is not a coding agent, so it does not chat here.": "Browser Use est une bibliothèque open source qui permet à un modèle d’IA de piloter un navigateur web pour accomplir une tâche. Elle tourne sur un ordinateur avec Python et demande une clé du modèle d’IA utilisé (son cloud offre un peu de crédit aux nouveaux comptes, puis devient payant). Il n’existe pas de version Android et ce n’est pas un agent de programmation : il ne discute donc pas ici.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "Automatisation du navigateur. Nécessite Node et le téléchargement de Chromium, ce qui peut être lourd sur un téléphone.",
