"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "Modifier le thème et les overlays passe par le shell. Connectez un mode dans Modes de fonctionnement, puis revenez.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "Modifier le thème et les overlays passe par le shell. Connectez un mode dans Modes de fonctionnement, puis revenez. Les couleurs utilisées actuellement s’affichent même sans mode connecté.",
"Changing this can break setup, apps or the system. Only change it if you know what it does.": "Modifier ceci peut perturber la configuration, des applications ou le système. Ne le modifiez que si vous savez ce que cela fait.",
