"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Choisissez le mode de connexion dans le panneau de connexion de l’agent. Les outils sans version Android s’installent dans un environnement Debian au sein de Termux. Cela prend plusieurs minutes et jusqu’à environ 1 GB ; les fournisseurs ne prennent pas Android officiellement en charge, donc un outil peut ne pas fonctionner sur tous les téléphones.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Choisissez ce que fait le bouton supplémentaire de chaque ligne de la liste des applications. C’est toujours une icône, et celles qui changent selon l’application (Activer / Désactiver, Installer / Désinstaller, Réactiver / Suspendre) adaptent leur icône et leur action à l’état actuel de l’application.",
"Choose what to install and which starter files to write": "Choisissez quoi installer et quels fichiers de départ écrire",
"Choosing a folder needs the app build": "Choisir un dossier nécessite la version app",
"Choosing files works in the app": "Le choix de fichiers fonctionne dans l’application",
"Chosen:": "Choisi :",
"Classic three-button navigation bar": "Barre de navigation classique à trois boutons",
"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro ou Max et la connexion avec un compte Google ne peuvent être utilisés que dans les applications des fournisseurs eux-mêmes : Anthropic et Google n’autorisent pas les autres applications à utiliser ces identifiants. Le Terminal vous connecte donc via les outils officiels en ligne de commande qui s’exécutent dans Termux, où s’ouvre la page de connexion du site du fournisseur :",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "Nettoyez ce qui n’est plus nécessaire : fichiers superflus, données superflues des applications, restes d’applications disparues et fichiers en double. Analysez d’abord, regardez la liste, retirez ce que vous voulez garder, puis supprimez. Les quatre outils utilisent le mode de fonctionnement de cette application pour les dossiers qu’une application normale ne peut pas lire.",
"Clean — no engine flagged this file": "Sain — aucun moteur n’a signalé ce fichier",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "Le nettoyage est simulé. Les fichiers sont analysés et signalés, mais rien n’est réellement supprimé.",
