"Crawl4AI": "Crawl4AI",
"Crawl4AI is an open-source web crawler that turns web pages into clean text for AI models. The library and its Docker server are free, but run on a computer, not on Android; its hosted cloud is pay-as-you-go. It is not a coding agent, so it does not chat here.": "Crawl4AI est un robot d’exploration web open source qui transforme les pages web en texte propre pour les modèles d’IA. La bibliothèque et son serveur Docker sont gratuits, mais tournent sur un ordinateur, pas sur Android ; son cloud hébergé est facturé à l’usage. Ce n’est pas un agent de programmation : il ne discute donc pas ici.",
