"For a coding agent that runs right here in Termux instead, choose OpenCode, or one of the API-key / sign-in agents above.": "Pour un agent de codage qui s’exécute directement ici dans Termux, choisissez plutôt OpenCode, ou l’un des agents à clé d’API ou à connexion ci-dessus.",
"For a free assistant on this phone, choose Ollama (on-device); for one on your computer, Jan.ai or AnythingLLM.": "Pour un assistant gratuit sur ce téléphone, choisissez Ollama (sur l’appareil) ; pour un assistant sur votre ordinateur, Jan.ai ou AnythingLLM.",
"For an answer to an Ask agent button, choose an agent above that has a key or runs on your own server; with none, the button still offers the free Web search.": "Pour obtenir une réponse à un bouton Demander à l’agent, choisissez plus haut un agent avec une clé ou sur votre propre serveur ; sans agent, le bouton propose la recherche web gratuite.",
