"Force-stop apps before clearing their cache. It can help clear some apps' caches, but may cause apps to misbehave and require manual restart.": "Force l’arrêt des applications avant de vider leur cache. Cela peut aider à vider le cache de certaines applications, mais peut les faire mal fonctionner et nécessiter un redémarrage manuel.",
