"Format": "Format",
"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Trouvé en lisant les noms de classes dans le code de l’application sur ce téléphone ; rien n’est envoyé nulle part. Liste de traqueurs : Exodus Privacy, sous licence ODbL 1.0. Un code renommé par un réducteur (R8, ProGuard) ou chargé plus tard peut cacher un traqueur : un petit nombre ne prouve donc pas qu’il n’y en a aucun.",
"Found in Downloads": "Trouvé dans Téléchargements",
"Free": "Libre",
"Free Open-Source": "Gratuit et open source",
