"Free and open-source: on your computer or on this phone": "Gratuit et open source : sur votre ordinateur ou sur ce téléphone",
"Free storage space": "Espace de stockage libre",
"Free up storage by clearing the cache of every app on your phone in one go.": "Libérez de l’espace en vidant le cache de chaque application du téléphone en une seule fois.",
