"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "Geler, débloater, installer, sauvegarder et inspecter toutes les applications de votre téléphone, directement depuis le téléphone : via ADB, le débogage sans fil, Shizuku ou Root. Sans ordinateur, sans compte, sans publicité.",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "Depuis le gestionnaire de fichiers : installation via un backend privilégié, avec les vérifications de signature de cette application désactivées. Android vérifie toujours lui-même les signatures : un APK dont il ne peut pas vérifier la signature est signé avec la clé de cette application puis installé, et une application signée par quelqu’un d’autre ne peut être remplacée qu’après avoir été désinstallée (une confirmation vous est demandée au préalable).",
