"Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse and Deepseek connect with an API key from the provider's website (links below). Usage is billed by the provider to that key's account; Google's Gemini API also has a free tier, where Google may use what you send to improve its products.": "Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse et Deepseek se connectent avec une clé d’API du site du fournisseur (liens ci-dessous). L’utilisation est facturée par le fournisseur au compte de cette clé ; l’API Gemini de Google propose aussi un niveau gratuit, où Google peut utiliser ce que vous envoyez pour améliorer ses produits.",
