"Installing Ollama": "Installation d’Ollama",
"Installing from File Manager runs through ADB, Wireless Debugging, Shizuku or Root, and none of them is connected right now.": "L’installation depuis le gestionnaire de fichiers passe par ADB, le débogage sans fil, Shizuku ou Root, et aucun n’est connecté pour le moment.",
"Installing...": "Installation...",
"Installing…": "Installation…",
"Installs Ollama in Termux, starts it and downloads a small coding model (qwen2.5-coder 1.5B, about 1 GB). This takes a few minutes.": "Installe Ollama dans Termux, le démarre et télécharge un petit modèle de code (qwen2.5-coder 1.5B, environ 1 GB). Cela prend quelques minutes.",
"Installs from": "S’installe depuis",
"Installs from File Manager need ADB, Wireless Debugging or Shizuku": "Les installations depuis le gestionnaire de fichiers nécessitent ADB, le débogage sans fil ou Shizuku",
"Installs the backed-up APK over the installed one, then re-applies its permissions and app ops.": "Installe l’APK sauvegardé par-dessus celui qui est installé, puis réapplique ses autorisations et ses App Ops.",
"Installs the patched app through the working mode (ADB, Shizuku or Root) as soon as it is built.": "Installe l’application patchée via le mode de fonctionnement (ADB, Shizuku ou Root) dès qu’elle est construite.",
"Interface": "Interface",
"Interfaces": "Interfaces",
"Internal storage": "Stockage interne",
"Internal storage ›": "Stockage interne ›",
"Invalid source URL: the address must point to a GitHub or GitLab repository, or to a .json metadata file.": "URL de source non valide : l’adresse doit pointer vers un dépôt GitHub ou GitLab, ou vers un fichier de métadonnées .json.",
"Invalid source URL: the address must start with https.": "URL de source non valide : l’adresse doit commencer par https.",
"Is it safe to disable?": "Peut-on la désactiver sans risque ?",
"Issuer": "Émetteur",
"Issues": "Tickets",
"It could not be saved": "Impossible de l’enregistrer",
"It did not finish": "L’opération ne s’est pas terminée",
"It did not work": "Ça n’a pas fonctionné",
"It finishes installing itself the first time it opens.": "Il termine son installation à sa première ouverture.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "Il n’a pas de version Android : il s’installe donc dans un conteneur Debian au sein de Termux (plusieurs minutes, quelques centaines de MB). Les étapes déjà installées sont vite ignorées.",
"It has no value right now.": "Il n’a pas de valeur pour le moment.",
"It is connected now and stays connected. It is saved again the next time you connect it.": "Il est connecté maintenant et le reste. Il est enregistré à nouveau la prochaine fois que vous le connectez.",
"It is installed silently through the working mode.": "Il est installé silencieusement via le mode de fonctionnement.",
"It is not set any more": "Il n’est plus défini",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Elle est supprimée pour l’utilisateur de l’appareil. Une application système peut être remise avec Réinstaller.",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Il est d’abord essayé tel quel ; si Android le refuse, une copie signée avec la clé de cette application est installée.",
"It looks like a percentage.": "On dirait un pourcentage.",
"It looks like a time in seconds.": "On dirait une durée en secondes.",
"It looks like a web address.": "On dirait une adresse web.",
"It looks like an app component (package/class).": "On dirait un composant d’application (paquet/classe).",
"It looks like an app package name, or a list of them.": "On dirait un nom de paquet d’application, ou une liste de noms.",
"It looks like an on/off switch.": "On dirait un interrupteur activé/désactivé.",
"It needs your consent first.": "Il faut d’abord votre consentement.",
"Item": "Élément",
"Its patches are removed from this phone. Apps you already patched stay as they are.": "Ses patchs sont retirés de ce téléphone. Les applications déjà patchées restent telles quelles.",
"Its settings, accounts and files on the device are deleted.": "Ses paramètres, ses comptes et ses fichiers sur l’appareil sont supprimés.",
"Its value is a decimal number.": "Sa valeur est un nombre décimal.",
"Its value is a whole number.": "Sa valeur est un nombre entier.",
"Its value is text.": "Sa valeur est du texte.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "Page IzzyOnDroid",
"JVM code cache. Blocks of bytecode compiled into native code.": "Cache de code JVM. Blocs de bytecode compilés en code natif.",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan exécute des modèles d’IA sur votre ordinateur, gratuitement. Sur l’ordinateur : Jan, Settings, Local API Server : définissez l’hôte sur 0.0.0.0 et démarrez-le, puis saisissez ici l’adresse de l’ordinateur (par ex. http://192.168.1.20:1337/v1). Jan n’existe pas en version Android.",
"Jan.ai": "Jan.ai",
"Keep": "Conserver",
"Keep a copy of your saved lists in a folder of your choice, and bring them back from a backup file.": "Gardez une copie de vos listes enregistrées dans un dossier de votre choix, et restaurez-les depuis un fichier de sauvegarde.",
