"Keys and servers": "Clés et serveurs",
"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "Les clés sont chiffrées avec une clé qui reste dans le matériel sécurisé du téléphone, et ne sont jamais envoyées qu’à l’adresse de leur propre fournisseur. La page ne les voit plus après leur saisie ; seuls les quatre derniers caractères sont affichés.",
