"Let Termux take commands from other apps": "Permettre à Termux de recevoir les commandes d’autres applications",
"Let them act without asking": "Les laisser agir sans demander",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Permet à l’agent de lire et d’écrire des fichiers dans le dossier indiqué à la fin de la commande (remplacez /sdcard selon vos besoins).",
"Lets the agent think in explicit steps before it acts.": "Permet à l’agent de réfléchir par étapes explicites avant d’agir.",
"Lets this app change a few protected system settings used by some advanced features.": "Permet à cette application de modifier quelques paramètres système protégés utilisés par certaines fonctions avancées.",
