"Off: reading outside the current folder needs your OK.": "Désactivé : lire hors du dossier actuel nécessite votre accord.",
"Off: the patches that work are applied and the failed ones are reported.": "Désactivé : les patchs qui fonctionnent sont appliqués et ceux qui échouent sont signalés.",
"Offer to delete the file afterwards": "Proposer de supprimer le fichier ensuite",
