"Ollama": "Ollama",
"Ollama (on-device)": "Ollama (sur l’appareil)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama n’est pas encore lancé sur ce téléphone. Installez-le ci-dessous, ou saisissez l’adresse d’un ordinateur qui l’exécute.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone.": "Ollama exécute un modèle de code directement sur ce téléphone : gratuit, et hors ligne une fois le modèle téléchargé. Il s’installe dans Termux ; les petits modèles (1.5B à 3B) sont les plus adaptés à un téléphone.",
"On": "Activé",
"On device": "Sur l’appareil",
"On this phone": "Sur ce téléphone",
"On:": "Activé :",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "Une commande à la fois par shell ; les sorties longues sont tronquées à l’écran et dans ce qui est envoyé à un agent.",
"One file only": "Un seul fichier",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Une seule clé pour toute l’application. L’analyse de l’Installateur et celle de Morphe Helper l’utilisent ; ni l’une ni l’autre ne la redemande, elles renvoient seulement ici quand elle manque.",
"One more place to find apps": "Un endroit de plus pour trouver des applications",
"One package per line. Duplicate entries are removed automatically.": "Un package par ligne. Les doublons sont supprimés automatiquement.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Une couleur source, neuf façons d’en faire un thème complet : l’accent, l’arrière-plan, les cartes et le texte, en clair et en sombre. Choisir un style construit le thème à partir de la couleur source ci-dessous.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Seul AppCleaner l’utilise : il ouvre l’écran Infos de l’appli du système pour chaque application et touche Vider le cache, pour les caches qu’aucun accès aux fichiers n’atteint. Il ne fait rien d’autre, ne lit jamais ce qui est à l’écran en dehors de ces écrans, et s’arrête quand l’écran s’éteint.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "Seul un bloc marqué est écrit dans ces fichiers ; ce que vous y avez reste, et relancer ceci actualise le bloc au lieu d’en ajouter un autre.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "N’ajoutez que des sources de confiance. Une source de patchs décide de ce qui se retrouve dans vos applications patchées.",
"Only apps installed on this phone": "Seulement les applications installées sur ce téléphone",
"Only base": "Base uniquement",
"Only hidden files are here. Tick Show hidden files to see them.": "Il n’y a ici que des fichiers masqués. Cochez Afficher les fichiers masqués pour les voir.",
"Only include common media files, documents and archives.": "N’inclure que les fichiers multimédias, documents et archives courants.",
"Only list what would run for each app. Nothing is run.": "Liste seulement ce qui s’exécuterait pour chaque application. Rien n’est exécuté.",
"Only patches for apps installed on this phone": "Seulement les patchs d’applications installées sur ce téléphone",
"Only text and compiled XML files can be compared line by line": "Seuls les fichiers texte et XML compilés peuvent être comparés ligne par ligne",
"Only the lines written by the app you pick": "Seulement les lignes écrites par l’application choisie",
"Only the selected apps are saved.": "Seules les applications sélectionnées sont enregistrées.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Seul le texte de cette appli change ; les noms, chemins et commandes dans les zones de code gardent leur propre police.",
