"Phone makers and apps add settings of their own.": "Les fabricants de téléphones et les applications ajoutent leurs propres paramètres.",
"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "Choisissez un lot de patchs .mpp dans le stockage. Une source locale ne se met jamais à jour toute seule : choisissez le nouveau fichier quand il sort.",
