"Pick an agent under Coding Agents to chat": "Choisissez un agent dans Agents de codage pour discuter",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Choisissez un agent, puis le modèle et l’effort (Faible, Équilibré ou Élevé : à quel point on lui demande de réfléchir). La première fois, les deux démarrent sur un choix équilibré, et l’agent demande ce dont il a besoin (une clé d’API, une adresse de serveur ou une connexion) et le teste avant que vous commenciez.",
