"Termux is not set up for this app yet.": "Termux n’est pas encore configuré pour cette application.",
"Termux is ready: vim, nano, git and python are installed and bash has its starter .bashrc. Open the real terminal for full-screen programs.": "Termux est prêt : vim, nano, git et python sont installés et bash a son .bashrc de départ. Ouvrez le vrai terminal pour les programmes en plein écran.",
"Termux permission": "Autorisation Termux",
"Termux setup": "Configuration de Termux",
"Termux shells read ~/.bash_profile or ~/.profile first (PATH and the like). Turn off if your profile starts another program.": "Les shells Termux lisent d’abord ~/.bash_profile ou ~/.profile (PATH, etc.). Désactivez si votre profil lance un autre programme.",
