"That part of the guide is not there.": "Cette partie du guide n’existe pas.",
"That password did not work. Try again.": "Ce mot de passe n'a pas fonctionné. Réessayez.",
"That pattern could freeze the list (a repeat inside a repeat, or very long), so it is searched as plain text.": "Ce motif pourrait bloquer la liste (une répétition dans une répétition, ou très long), il est donc recherché comme du texte brut.",
"That port is used by this phone's own ADB. Use another, like 4444.": "Ce port est utilisé par l’ADB de ce téléphone. Utilisez-en un autre, comme 4444.",
"That recording could not be read": "Cet enregistrement n’a pas pu être lu",
"That source did not answer": "Cette source n’a pas répondu",
"That source did not work": "Cette source n’a pas fonctionné",
"That source did not work Trying the other sources...": "Cette source n’a pas fonctionné. Essai des autres sources...",
"The # button switches to commands.": "Le bouton # passe aux commandes.",
"The $ button switches to commands.": "Le bouton $ passe aux commandes.",
"The ADB key and the APK-signing key are created on this phone and never leave it.": "La clé ADB et la clé de signature d’APK sont créées sur ce téléphone et ne le quittent jamais.",
"The APK": "L’APK",
"The APK is ready (saved from the browser).": "L’APK est prêt (enregistré depuis le navigateur).",
"The APK is ready.": "L’APK est prêt.",
"The Action Button": "Le bouton d’action",
"The Bluetooth link could not be set up.": "Impossible d’établir la liaison Bluetooth.",
"The Coding Agent that answers every Ask agent button: what a hidden setting, a permission, a process, a log line or an app is. Its key or sign-in is set up in the Command-Line Interface tab.": "L’agent de codage qui répond à chaque bouton « Demander à l’agent » : ce qu’est un paramètre caché, une autorisation, un processus, une ligne de journal ou une application. Sa clé ou sa connexion se configure dans l’onglet Ligne de commande.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "Le bouton MCP ouvre un panneau pour donner à un agent des outils supplémentaires (fichiers, web, navigateur, GitHub...) via le Model Context Protocol. Choisissez un préréglage ou écrivez le vôtre : un nom, une commande locale ou une adresse distante, et toute clé ou en-tête nécessaire. Choisissez les agents auxquels l’ajouter : le même serveur peut aller dans plusieurs à la fois, puisque chaque agent le conserve dans son propre fichier.",
"The Morphe engine is not in this build of the app": "Le moteur Morphe n’est pas dans cette version de l’application",
"The PDF could not be shown.": "Impossible d’afficher le PDF.",
"The Rish shell ended. Tap Rish mode to open a new one.": "Le shell Rish s’est terminé. Appuyez sur Mode Rish pour en ouvrir un nouveau.",
"The Rish shell is no longer running.": "Le shell Rish ne s’exécute plus.",
"The Terminal needs the app (it is not available in a plain browser)": "Le Terminal nécessite l’application (il n’est pas disponible dans un simple navigateur)",
"The UAD-NG list has not been downloaded yet.": "La liste UAD-NG n’a pas encore été téléchargée.",
"The UAD-NG list has nothing on this app": "La liste UAD-NG ne dit rien sur cette application",
"The VirusTotal scan did not work": "L’analyse VirusTotal n’a pas fonctionné",
"The accessibility service is not ready": "Le service d’accessibilité n’est pas prêt",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Le service d’accessibilité n’est pas prêt (il n’est pas connecté) : les caches que lui seul peut vider restent. Ensuite, utilisez « Effacer le reste avec l’accessibilité » sur la carte AppCleaner.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Le service d’accessibilité n’est pas prêt (il est désactivé) : les caches que lui seul peut vider restent. Ensuite, utilisez « Effacer le reste avec l’accessibilité » sur la carte AppCleaner.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Le service d’accessibilité n’est pas prêt (aucun consentement donné) : les caches que lui seul peut vider restent. Ensuite, utilisez « Effacer le reste avec l’accessibilité » sur la carte AppCleaner.",
"The account has no credit left, or a spending limit was reached.": "Le compte n’a plus de crédit, ou une limite de dépenses a été atteinte.",
"The agent is still working: STOP it first": "L’agent travaille encore : arrêtez-le d’abord avec STOP",
"The agent pauses after this many steps.": "L’agent se met en pause après ce nombre d’étapes.",
"The app": "L’application",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "L’application est gratuite et le restera. Si elle vous a fait gagner du temps, un café m’aide à continuer de l’améliorer. Totalement facultatif, et merci !",
"The app version, Android version and phone model, so a problem is easier to find.": "La version de l’application, la version d’Android et le modèle du téléphone, pour qu’un problème soit plus facile à trouver.",
"The apps you patch are listed here, with the log of each run, so you can install them again, share them or save them to Downloads.": "Les applications que vous patchez sont listées ici, avec le journal de chaque exécution, pour pouvoir les réinstaller, les partager ou les enregistrer dans Téléchargements.",
"The archive file is rewritten without this file.": "Le fichier d’archive est réécrit sans ce fichier.",
"The archive file is rewritten without this folder and everything in it.": "Le fichier d’archive est réécrit sans ce dossier ni son contenu.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "L'archive n'est supprimée que si tous ses fichiers ont été extraits, sans exception.",
"The archive job failed": "La tâche d’archive a échoué",
"The browser did not open": "Le navigateur ne s’est pas ouvert",
