"The edit could not start": "La modification n’a pas pu démarrer",
"The exclusions SD Maid SE ships with come back, the ones you removed too. Yours stay.": "Les exclusions fournies avec SD Maid SE reviennent, y compris celles que vous aviez retirées. Les vôtres restent.",
"The exclusions could not be read.": "Les exclusions n’ont pas pu être lues.",
"The extra button on every row of the Apps list. Choose what a tap on it does. Press and hold it on a row for a sheet with every action for that app.": "Le bouton supplémentaire sur chaque ligne de la liste des Applications. Choisissez ce que fait un appui dessus. Maintenez-le sur une ligne pour une feuille avec toutes les actions de cette application.",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "Les touches supplémentaires fonctionnent comme celles de Termux : ESC efface la ligne, TAB complète un nom de fichier, CTRL-C arrête ce qui s’exécute, les flèches parcourent les commandes précédentes et déplacent le curseur, HOME et END sautent dans la ligne, et | / - ~ sont là parce que les claviers de téléphone les masquent.",
"The extraction could not start": "Impossible de démarrer l'extraction",
"The file": "Le fichier",
"The file and its log are removed. The app on the phone is not touched.": "Le fichier et son journal sont supprimés. L’application sur le téléphone n’est pas touchée.",
"The file chooser needs the app build": "Le sélecteur de fichiers nécessite la version de l'appli",
"The file is removed from this phone's storage, not just from the list. An Undo bar stays for a few seconds, and the file only goes for good once that bar is gone.": "Le fichier est supprimé du stockage de ce téléphone, pas seulement de la liste. Une barre Annuler reste affichée quelques secondes, et le fichier n’est définitivement supprimé qu’une fois cette barre disparue.",
"The file was saved, but it is not an app file (unknown). Choose another download in the browser.": "Le fichier a été enregistré, mais ce n’est pas un fichier d’application (inconnu). Choisissez un autre téléchargement dans le navigateur.",
