"The name in code type is the key. It is the same on every phone that has the setting.": "Le nom en type code est la clé. Il est identique sur tous les téléphones qui ont ce réglage.",
"The older storage permission some apps still check for.": "L’ancienne autorisation de stockage que certaines applications vérifient encore.",
"The pairing code has 6 digits": "Le code d’association comporte 6 chiffres",
"The password is used only for this archive, only while it is open. It is never saved.": "Le mot de passe n'est utilisé que pour cette archive, et seulement pendant qu'elle est ouverte. Il n'est jamais enregistré.",
"The patch bundle may be damaged or made for a newer Morphe. Update the source in Sources.": "Le lot de patchs est peut-être endommagé ou conçu pour un Morphe plus récent. Mettez la source à jour dans Sources.",
