"The patched APK was deleted after the install.": "L’APK patché a été supprimé après l’installation.",
"The patcher could not be started": "Le patcheur n’a pas pu être démarré",
"The patcher ran out of memory. Close other apps and try again, or turn on \"Strip unused native libraries\" in the patcher settings.": "Le patcheur a manqué de mémoire. Fermez d’autres applications et réessayez, ou activez « Retirer les bibliothèques natives inutilisées » dans les paramètres du patcheur.",
"The patcher stopped": "Le patcheur s’est arrêté",
"The patcher stops and nothing is saved.": "Le patcheur s’arrête et rien n’est enregistré.",
"The patches could not be read": "Les patchs n’ont pas pu être lus",
"The patches do not support this version of the app. Get a supported version with Morphe Helper, or turn on \"Patch unsupported versions\" in the patcher settings.": "Les patchs ne prennent pas en charge cette version de l’application. Obtenez une version prise en charge avec Morphe Helper, ou activez « Patcher les versions non prises en charge » dans les paramètres du patcheur.",
"The paths could not be read.": "Les chemins n’ont pas pu être lus.",
"The phone may still apply it. It is looked at again in a moment.": "Le téléphone peut encore l’appliquer. Une nouvelle vérification a lieu dans un instant.",
"The phone may still apply it. The list is read again in a moment.": "Le téléphone peut encore l’appliquer. La liste est relue dans un instant.",
"The phone's browser": "Le navigateur du téléphone",
"The project gives no description for this package.": "Le projet ne fournit aucune description pour ce package.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "Les fournisseurs ne prennent pas Android officiellement en charge : l’outil peut ne pas fonctionner sur tous les téléphones. Le Terminal affiche ses messages exacts en cas d’échec.",
"The pull did not finish": "La récupération ne s’est pas terminée",
"The push did not finish": "L’envoi ne s’est pas terminé",
"The quick brown fox jumps over the lazy dog.": "The quick brown fox jumps over the lazy dog.",
