"The request could not be sent": "Impossible d’envoyer la requête",
"The request could not start": "La requête n’a pas pu démarrer",
"The resolution the device draws at, width x height in pixels.": "La résolution d’affichage de l’appareil, largeur x hauteur en pixels.",
"The round checkmark button (when apps are selected)": "Le bouton rond à coche (quand des applications sont sélectionnées)",
"The scan failed: unknown error": "L’analyse a échoué : erreur inconnue",
"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "L’écran affiche un instant les paramètres d’une application après l’autre pendant que Vider le cache est touché pour chaque application qui a encore un cache que les fichiers n’atteignent pas. Un voile montre ce qui se passe, avec un bouton Annuler. Cela s’arrête si l’écran s’éteint.",
