"These apps are currently selected for this action:": "Ces applications sont actuellement sélectionnées pour cette action :",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Ces applications sont désinstallées mais leurs dossiers de données sont toujours sur le téléphone. Les données des applications que vous cochez sont supprimées définitivement.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Ces applications sont désinstallées. Sans Root, l’application ne peut pas voir lesquelles ont encore des données ; tout effacer est donc sans risque mais peut ne rien trouver pour certaines. Les données des applications que vous cochez sont supprimées définitivement.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Les versions de ces applications sont publiées sur des sites que cette application ne peut pas vérifier directement. Obtainium peut les suivre.",
"These files are too different to compare line by line. View each one instead.": "Ces fichiers sont trop différents pour être comparés ligne par ligne. Affichez-les plutôt un par un.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Ils continuent quand le navigateur est fermé. Pause conserve ce qui a été téléchargé et Reprendre ne demande au site que le reste (un site qui ne le permet pas recommence le fichier).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Ils seront ignorés sauf si vous patchez quand même, ce qui peut échouer ou casser l’application.",
"Third-party packages only": "Packages tiers uniquement",
"This App's ADB Key": "Clé ADB de cette application",
"This Shizuku version is too old. Please update Shizuku.": "Cette version de Shizuku est trop ancienne. Veuillez mettre à jour Shizuku.",
"This action cannot be undone.": "Cette action est irréversible.",
"This action needs access to files on this phone.": "Cette action nécessite l’accès aux fichiers de ce téléphone.",
"This agent": "Cet agent",
"This agent has no sign-in tool": "Cet agent n’a pas d’outil de connexion",
"This app": "Cette application",
"This app (sandbox)": "Cette application (sandbox)",
"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Cette appli ne peut pas lire le stockage. Accordez l'accès à tous les fichiers, ou choisissez un fichier de police à la main (aucun accès requis).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Cette application ne demande pas d’écran tactile, de clavier ou de navigation particulier (elle n’a pas d’entrée uses-configuration) : elle s’exécute donc avec ce que ce téléphone possède.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Cette application ne déclare aucune fonctionnalité matérielle ou logicielle requise (aucune entrée uses-feature).",
"This app has no activities.": "Cette application n’a aucune activité.",
"This app may not run commands in Termux yet.": "Cette application n’est peut-être pas encore autorisée à exécuter des commandes dans Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Cette application possède désormais sa propre clé ADB privée. Appuyez sur le badge du mode pour plus de détails.",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "Le code de cette application n’a pas pu être lu (il n’y en a pas, ou le fichier est illisible) ; on ne peut donc rien dire sur les traqueurs.",
"This app's own shell - no root, ADB or package manager.": "Le shell propre à cette application : pas de root, d’ADB ni de gestionnaire de packages.",
"This app's own user and group id": "L’ID d’utilisateur et de groupe propre à cette application",
"This app’s key · 2048-bit RSA · in secure hardware": "Clé de cette application · RSA 2048 bits · dans le matériel sécurisé",
"This app’s key · 2048-bit RSA · in the Android Keystore": "Clé de cette application · RSA 2048 bits · dans l’Android Keystore",
"This archive is view-only": "Cette archive est en lecture seule",
"This build": "Ce build",
"This build of the app does not contain the Morphe engine, so patching is not available. Sources, the community finder and downloads still work. Install a release build of the app to patch.": "Cette version de l’application ne contient pas le moteur Morphe, le patch n’est donc pas disponible. Les sources, la recherche communautaire et les téléchargements fonctionnent toujours. Installez une version de publication de l’application pour patcher.",
"This build of the app does not contain the Morphe engine. Install a release build.": "Cette version de l’application ne contient pas le moteur Morphe. Installez une version de publication.",
"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "Cela peut couper la connexion ADB que cette application utilise ; vous ne pourrez peut-être pas le rétablir depuis ici.",
"This can lock you out of parts of the phone (the screen, the keyboard or accessibility).": "Cela peut vous bloquer l’accès à certaines parties du téléphone (l’écran, le clavier ou l’accessibilité).",
"This cannot be undone.": "Cette action est irréversible.",
"This device has not allowed this phone yet. Look at its screen and tap": "Cet appareil n’a pas encore autorisé ce téléphone. Regardez son écran et appuyez sur",
"This file could not be read": "Ce fichier n’a pas pu être lu",
