"This font could not be shown.": "Impossible d’afficher cette police.",
"This is already what the phone uses.": "C’est déjà ce que le téléphone utilise.",
"This is not a text file. Use View, or Open with…": "Ce n’est pas un fichier texte. Utilisez Afficher ou Ouvrir avec…",
"This is the top of this storage": "Vous êtes à la racine de ce stockage",
"This look is an old custom palette: choose a palette or a palette style first": "Cette apparence est une ancienne palette personnalisée : choisissez d’abord une palette ou un style de palette",
"This looks like a binary file. Pull it to this phone instead.": "Ceci ressemble à un fichier binaire. Récupérez-le plutôt sur ce téléphone.",
"This needs the app build.": "Cela nécessite le build de l’application.",
"This only works with the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); an agent used only with an API key cannot use one here.": "Cela ne fonctionne qu’avec les agents qui se connectent via leur propre outil en ligne de commande dans Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) ; un agent utilisé uniquement avec une clé d’API ne peut pas en utiliser ici.",
"This package carries data files that live outside the APK. Right after the install succeeds they are copied into place.": "Ce package contient des fichiers de données situés en dehors de l’APK. Dès que l’installation réussit, ils sont copiés à leur place.",
"This page is running without the app, so there is no phone to read the settings from.": "Cette page s’exécute sans l’application, il n’y a donc aucun téléphone pour lire les paramètres.",
