"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "Pour supprimer des doublons, SD Maid décide quel fichier garder en vérifiant chaque critère dans l’ordre. Le premier critère qui donne un gagnant net détermine le résultat. Faites glisser pour réordonner, touchez pour changer de mode.",
