"You can grant or revoke it here.": "Vous pouvez l’accorder ou la révoquer ici.",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "Vous avez modifié cet APK : sa signature n’est donc plus valide et Android ne l’installera pas tel quel.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "Vous expliquez un paramètre caché d’Android (une entrée de la base de données Settings.Global, Settings.Secure ou Settings.System, celles que « settings get/put » lit et écrit) à quelqu’un qui n’est pas développeur.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "Vous expliquez un paramètre caché d’Android (une entrée de la base de données Settings.Global, Settings.Secure ou Settings.System, celles que « settings get/put » lit et écrit) à quelqu’un qui n’est pas développeur. Dites brièvement : ce qu’il contrôle, ce que ses valeurs signifient, ce que le modifier provoque, et s’il est sûr de le modifier. Dites clairement quand vous ne connaissez pas le paramètre (beaucoup viennent du fabricant du téléphone) au lieu de deviner, puis dites ce que son nom suggère. Paragraphes courts, sans titres.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "Vous expliquez une entrée logcat d’Android à quelqu’un qui n’est pas développeur. Dites, en mots simples et brièvement : ce que signifie cette ligne,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "Vous expliquez une entrée logcat d’Android à quelqu’un qui n’est pas développeur. Dites, en mots simples et brièvement : ce que signifie cette ligne, la cause la plus probable, si cela compte (bruit inoffensif, vrai problème ou plantage) et, si cela compte, ce qu’il faut essayer. Utilisez des paragraphes courts, sans titres. Si la ligne est trop obscure pour être expliquée avec certitude, dites-le et dites ce qui aiderait d’autre. N’inventez pas de détails.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "Vous aidez sur ADB et la syntaxe des commandes shell dans un terminal Android. Répondez brièvement et de façon pratique.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "Vous aidez sur ADB et la syntaxe des commandes shell dans un terminal Android. Répondez brièvement et de façon pratique. Si vous voulez proposer à l’utilisateur exactement une commande à exécuter ici, placez-la seule dans",
